import sys
from math import fsum
def main():
    data=sys.stdin.buffer.read()
    flat=data.replace(b',',b'\n').split(b'\n')
    if flat and not flat[-1]: flat.pop()
    cats=flat[4::3]
    vals=list(map(float,flat[5::3]))
    lists={c:[] for c in set(cats)}
    ap={c:l.append for c,l in lists.items()}
    for c,v in zip(cats,vals):
        ap[c](v)
    sys.stdout.write(''.join('%s,%.2f\n'%(k.decode(),fsum(l)) for k,l in sorted(lists.items())))
main()
